function readDiskSceneScriptVersion() {
  var sceneScriptPath = path.resolve(__dirname, '..', 'scene-script.js');
  try {
    var source = fs.readFileSync(sceneScriptPath, 'utf8');
    var match = /MCP_SCENE_SCRIPT_VERSION\s*=\s*['"]([^'"]+)['"]/.exec(source);
    return {
      ok: !!match,
      version: match && match[1] || null,
      path: sceneScriptPath,
      error: match ? null : 'MCP_SCENE_SCRIPT_VERSION literal not found',
    };
  } catch (e) {
    return {
      ok: false,
      version: null,
      path: sceneScriptPath,
      error: e.message || String(e),
    };
  }
}

