  return ['<?xml version="1.0" encoding="UTF-8"?>','<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">','<plist version="1.0">','<dict>','  <key>frames</key>','  <dict>','    <key>neutral_red.png</key>','    <dict>','      <key>frame</key><string>{{0,0},{16,16}}</string>','      <key>offset</key><string>{0,0}</string>','      <key>rotated</key><false/>','      <key>sourceSize</key><string>{16,16}</string>','    </dict>','    <key>neutral_green.png</key>','    <dict>','      <key>frame</key><string>{{16,0},{16,16}}</string>','      <key>offset</key><string>{0,0}</string>','      <key>rotated</key><false/>','      <key>sourceSize</key><string>{16,16}</string>','    </dict>','    <key>neutral_blue_rotated.png</key>','    <dict>','      <key>frame</key><string>{{32,0},{16,24}}</string>','      <key>offset</key><string>{0,0}</string>','      <key>rotated</key><true/>','      <key>sourceSize</key><string>{24,16}</string>','    </dict>','    <key>neutral_checker.png</key>','    <dict>','      <key>frame</key><string>{{0,16},{32,32}}</string>','      <key>offset</key><string>{0,0}</string>','      <key>rotated</key><false/>','      <key>sourceSize</key><string>{32,32}</string>','    </dict>','  </dict>','  <key>metadata</key>','  <dict>','    <key>format</key><integer>2</integer>','    <key>realTextureFileName</key><string>' + imageName + '</string>','    <key>textureFileName</key><string>' + imageName + '</string>','    <key>size</key><string>{64,64}</string>','  </dict>','</dict>','</plist>'].join('\n');
