var SCRIPT_TEMPLATE = [
  "import { _decorator, Component } from 'cc';",
  'const { ccclass, property } = _decorator;',
  '',
  '@ccclass',
  'export class NewComponent extends Component {',
  '',
  '    onLoad() {',
  '    }',
  '',
  '    start() {',
  '    }',
  '}',
].join('\n');

function assertNotStructuredAssetPath(target, operation) {
  if (/\.(scene|prefab|fire|meta)$/i.test(String(target || ''))) {
    throw new Error((operation || 'Operation') + ' refused for structured Cocos asset: ' + target);
  }
}

function getProjectPath() {
  try { return Editor.Project.path; } catch (e) { return process.cwd(); }
}

function quotePowerShellSingle(value) {
  return "'" + String(value || '').replace(/'/g, "''") + "'";
}

function inspectCocosLaunchSafety(options) {
  options = options || {};
  var projectPath = String(options.projectPath || getProjectPath() || '');
  var result = {
    ok: true,
    status: 'ok',
    checked: false,
    platform: process.platform,
    projectPath: projectPath,
    unsafeFlag: '--can-show-upgrade-dialog true',
    processCount: 0,
    unsafeCount: 0,
    warningCount: 0,
    findings: [],
  };

  if (process.platform !== 'win32') {
    result.status = 'skipped';
    result.skipped = true;
    result.reason = 'Cocos process command-line safety scan is currently implemented for Windows editor automation only.';
    return result;
  }

  try {
    var childProcess = require('child_process');
    var script = [
      "$ErrorActionPreference = 'Stop';",
      '$project = ' + quotePowerShellSingle(projectPath) + ';',
      "$items = Get-CimInstance Win32_Process | Where-Object { $_.Name -eq 'CocosCreator.exe' -and $_.CommandLine -like '*--project*' -and $_.CommandLine -like ('*' + $project + '*') } | Select-Object ProcessId,CommandLine;",
      '$items | ConvertTo-Json -Depth 4',
    ].join(' ');
    var stdout = childProcess.execFileSync('powershell.exe', ['-NoProfile', '-ExecutionPolicy', 'Bypass', '-Command', script], {
      encoding: 'utf8',
      timeout: 5000,
      windowsHide: true,
    });
    var text = String(stdout || '').trim();
    var processes = [];
    if (text) {
      var parsed = JSON.parse(text);
      processes = Array.isArray(parsed) ? parsed : [parsed];
    }
    result.checked = true;
    result.processCount = processes.length;
    result.findings = processes.map(function (item) {
      var commandLine = String(item.CommandLine || item.commandLine || '');
      var canShowUpgradeDialog = /--can-show-upgrade-dialog(?:\s+|=)true/i.test(commandLine);
      return {
        processId: item.ProcessId || item.processId || null,
        unsafe: false,
        warning: canShowUpgradeDialog,
        canShowUpgradeDialog: canShowUpgradeDialog,
        commandLine: commandLine,
      };
    });
    result.unsafeCount = result.findings.filter(function (item) { return item.unsafe; }).length;
    result.warningCount = result.findings.filter(function (item) { return item.warning; }).length;
    result.ok = result.unsafeCount === 0;
    result.status = result.ok ? (result.warningCount ? 'warning' : 'ok') : 'blocked';
    if (result.warningCount) {
      result.warning = 'Cocos Creator command line includes --can-show-upgrade-dialog true. This is treated as informational because Creator may add it during normal manual startup; actual dialog-prone open/close/switch/save operations remain guarded separately.';
    }
    if (!result.ok) {
      result.missingCapability = 'dialog_safe_cocos_editor_launch';
      result.interactivePromptSuppressed = true;
      result.reason = 'Cocos launch safety found a hard dialog risk during unattended MCP automation.';
      result.nextSuggestedFix = 'Resolve the hard launch safety finding before running mutating MCP automation.';
    }
    return result;
  } catch (e) {
    result.ok = false;
    result.status = 'unknown';
    result.checked = false;
    result.error = e.message || String(e);
    result.missingCapability = 'cocos_process_launch_safety_scan';
    result.nextSuggestedFix = 'Verify the Cocos Creator process command line manually or fix the Windows process scan before mutating MCP automation.';
    return result;
  }
}

