function loadAssetRoleConfig() {
  var configPath = getAssetRoleConfigPath();
  if (!fs.existsSync(configPath)) {
    return { version: 1, roles: {}, conventions: {}, path: configPath, missing: true };
  }
  var raw = fs.readFileSync(configPath, 'utf8').replace(/^\uFEFF/, '');
  var parsed = JSON.parse(raw);
  parsed.roles = parsed.roles || {};
  parsed.conventions = parsed.conventions || {};
  parsed.path = configPath;
  return parsed;
}

function assetTypeToListType(type) {
  var normalized = String(type || 'all').toLowerCase();
  if (normalized === 'spriteframe' || normalized === 'sprite-frame') return 'sprite-frame';
  if (normalized === 'prefab') return 'prefab';
  if (normalized === 'font') return 'font';
  if (normalized === 'audio' || normalized === 'audioclip' || normalized === 'audio-clip') return 'audio-clip';
  if (normalized === 'texture' || normalized === 'image') return 'texture';
  return normalized || 'all';
}

function roleSearchTokens(role, entry) {
  var tokens = [];
  function add(value) {
    if (!value) return;
    String(value).split(/[^A-Za-z0-9]+/).forEach(function (part) {
      if (part) tokens.push(part.toLowerCase());
    });
  }
  add(role);
  add(entry && entry.category);
  if (role.indexOf('_') >= 0) add(role.replace(/_/g, ' '));
  return Array.from(new Set(tokens)).filter(function (token) { return token.length >= 3; });
}

async function firstExistingAssetPath(paths) {
  for (var i = 0; i < paths.length; i++) {
    var candidatePath = paths[i];
    try {
      var uuid = await editorHelpers.urlToUuid(candidatePath);
      if (uuid) return { path: candidatePath, uuid: uuid };
    } catch (e) {}
  }
  return null;
}

function dbAssetUrlToFspath(url) {
  var text = String(url || '');
  if (text.indexOf('db://assets') !== 0) return null;
  var rel = text.replace('db://assets', '').replace(/^\/+/, '');
  return path.join(getProjectPath(), 'assets', rel);
}

async function ensureAssetParentDirectory(assetUrl) {
  var fspath = dbAssetUrlToFspath(assetUrl);
  if (!fspath) return null;
  var dir = path.dirname(fspath);
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });

  var assetsRoot = path.join(getProjectPath(), 'assets');
  var relDir = path.relative(assetsRoot, dir).replace(/\\/g, '/');
  var dbDir = relDir ? 'db://assets/' + relDir : 'db://assets';
  try { await editorHelpers.refreshAssetDb(dbDir); } catch (e) {}
  return dbDir;
}

async function resolveDefaultInternalSprite() {
  return await firstExistingAssetPath(INTERNAL_SPRITE_CANDIDATES);
}

function dbUrlDir(url) {
  var text = String(url || '');
  var idx = text.lastIndexOf('/');
  return idx >= 0 ? text.substring(0, idx) : text;
}

function dbUrlBasename(url) {
  return path.basename(String(url || '').replace(/\\/g, '/'));
}

function normalizeAssetDbUrl(url, expectedExt, defaultName) {
  var text = String(url || '').replace(/\\/g, '/');
  if (!text) throw new Error('path is required');
  if (text.indexOf('db://assets/') !== 0 && text !== 'db://assets') {
    throw new Error('Only project-owned db://assets paths are supported: ' + text);
  }
  if (expectedExt && path.extname(text).toLowerCase() !== expectedExt.toLowerCase()) {
    if (/\/$/.test(text) || !path.extname(text)) {
      text = text.replace(/\/+$/, '') + '/' + (defaultName || ('NewAsset' + expectedExt));
    } else {
      throw new Error('Expected ' + expectedExt + ' asset path: ' + text);
    }
  }
  assertNotStructuredAssetPath(text, 'asset text write');
  return text;
}

async function getRecentConsoleEntries(startedAt, level, options) {
  options = options || {};
  var sinceTs = Number(startedAt || 0) || 0;
  var wantedLevel = level || 'error';
  var limit = Number(options.limit || 50) || 50;
  var entries = [];
  try {
    entries = logger.getLogs({ level: wantedLevel, limit: limit, sinceTs: sinceTs });
  } catch (e) {}
  try {
    entries = entries.concat(readProjectConsoleLogs({ level: wantedLevel, limit: limit, sinceTs: sinceTs }));
  } catch (e2) {}
  entries = entries.sort(function (a, b) { return Number(a.ts || 0) - Number(b.ts || 0); });
  entries = entries.slice(Math.max(0, entries.length - limit));
  var hints = options.hints || [];
  if (hints && hints.length) {
    var lowerHints = hints.map(function (hint) { return String(hint || '').toLowerCase(); }).filter(Boolean);
    entries = entries.filter(function (entry) {
      var text = String(entry.message || entry.text || entry.raw || '').toLowerCase();
      return lowerHints.some(function (hint) { return text.indexOf(hint) !== -1; });
    });
  }
  return entries;
}

async function getRecentConsoleErrors(startedAt, hints) {
  return await getRecentConsoleEntries(startedAt, 'error', { hints: hints || [], limit: 50 });
}

async function collectConsoleBaselineEvidence(startedAt, options) {
  options = options || {};
  var sinceTs = Number(startedAt || 0) || 0;
  if (!sinceTs) throw new Error('sinceTs or startedAt is required for baseline console verification');
  var limit = Number(options.limit || options.count || 100) || 100;
  var errors = [];
  var warnings = [];
  if (options.readConsole !== false) {
    errors = await getRecentConsoleEntries(sinceTs, 'error', { hints: options.hints || [], limit: limit });
    if (options.readWarnings !== false) {
      warnings = await getRecentConsoleEntries(sinceTs, 'warn', { hints: options.warningHints || [], limit: limit });
    }
  }
  var failOnWarnings = options.failOnWarnings === true;
  var endedAt = Date.now();
  return {
    ok: errors.length === 0 && (!failOnWarnings || warnings.length === 0),
    success: errors.length === 0 && (!failOnWarnings || warnings.length === 0),
    sinceTs: sinceTs,
    startedAt: sinceTs,
    endedAt: endedAt,
    durationMs: endedAt - sinceTs,
    errors: errors,
    warnings: warnings,
    consoleErrors: errors,
    consoleWarnings: warnings,
    errorCount: errors.length,
    warningCount: warnings.length,
    consoleErrorCount: errors.length,
    consoleWarningCount: warnings.length,
    failOnWarnings: failOnWarnings,
    policy: failOnWarnings
      ? 'No console errors or warnings emitted after the baseline are accepted.'
      : 'No console errors emitted after the baseline are accepted; warnings are reported as evidence.',
  };
}

async function collectOperationEvidence(startedAt, options) {
  options = options || {};
  var consoleEvidence = {
    sinceTs: startedAt,
    startedAt: startedAt,
    endedAt: Date.now(),
    durationMs: 0,
    errors: [],
    warnings: [],
    consoleErrors: [],
    consoleWarnings: [],
    errorCount: 0,
    warningCount: 0,
    ok: true,
    success: true,
  };
  if (options.readConsole !== false) {
    consoleEvidence = await collectConsoleBaselineEvidence(startedAt, {
      readConsole: true,
      readWarnings: options.readWarnings === true,
      failOnWarnings: options.failOnWarnings === true,
      hints: options.hints || [],
      warningHints: options.warningHints || [],
      limit: options.limit || 50,
    });
  }
  var endedAt = consoleEvidence.endedAt || Date.now();
  return {
    startedAt: startedAt,
    sinceTs: startedAt,
    endedAt: endedAt,
    durationMs: endedAt - startedAt,
    recentConsoleErrors: consoleEvidence.errors || [],
    consoleErrors: consoleEvidence.errors || [],
    recentConsoleWarnings: consoleEvidence.warnings || [],
    consoleWarnings: consoleEvidence.warnings || [],
    consoleEvidence: consoleEvidence,
  };
}

function attachOperationEvidence(result, evidence) {
  var out = (result != null && typeof result === 'object' && !Array.isArray(result))
    ? Object.assign({}, result)
    : { result: result == null ? null : result };
  out.startedAt = evidence.startedAt;
  out.sinceTs = evidence.sinceTs;
  out.endedAt = evidence.endedAt;
  out.durationMs = evidence.durationMs;
  out.recentConsoleErrors = evidence.recentConsoleErrors;
  out.consoleErrors = evidence.consoleErrors;
  out.recentConsoleWarnings = evidence.recentConsoleWarnings || [];
  out.consoleWarnings = evidence.consoleWarnings || [];
  out.consoleEvidence = evidence.consoleEvidence || null;
  out.ok = out.ok !== false && (!evidence.consoleEvidence || evidence.consoleEvidence.ok !== false);
  out.success = out.success !== false && out.ok !== false;
  out.operationEvidence = Object.assign({}, evidence);
  return out;
}

async function withOperationEvidence(startedAt, work, options) {
  var result = await work();
  var evidence = await collectOperationEvidence(startedAt, options || {});
  return attachOperationEvidence(result, evidence);
}

function isBuiltinUiMaterialResourceRef(refText) {
  var text = String(refText || '');
  return /(?:^|\|)_materials\[\d+\]\|.*\|Material$/i.test(text) || /(?:^|\|)_materials\[\d+\]\|\|[0-9a-f-]+\|Material$/i.test(text);
}

function filterIgnorableResourceRefsForDiff(refs) {
  return (Array.isArray(refs) ? refs : []).filter(function (refText) {
    return !isBuiltinUiMaterialResourceRef(refText);
  });
}

function parseNormalizedFullSpecResourceRef(refText) {
  var text = String(refText || '');
  var parts = text.split('|');
  return {
    raw: text,
    propertyPath: parts[0] || '',
    assetPath: parts[1] || '',
    uuid: parts[2] || '',
    assetType: parts[3] || '',
  };
}

function isBuiltinSkeletonMaterialResourceRef(refText) {
  var parsed = parseNormalizedFullSpecResourceRef(refText);
  if (parsed.propertyPath.indexOf('_materials[') !== 0) return false;
  if (String(parsed.assetType || '') && String(parsed.assetType) !== 'Material') return false;
  return !parsed.assetPath || /db:\/\/internal\/default_materials\//i.test(parsed.assetPath);
}

function normalizedResourceRefPathWithoutAtlasEnrichment(refText) {
  var parsed = parseNormalizedFullSpecResourceRef(refText);
  if (parsed.propertyPath === '_atlas' && parsed.assetType === 'SpriteAtlas') return '';
  return parsed.raw;
}

function areFullSpecResourceRefSetsEquivalent(componentType, sourceRefs, targetRefs) {
  var left = (Array.isArray(sourceRefs) ? sourceRefs : []).slice();
  var right = (Array.isArray(targetRefs) ? targetRefs : []).slice();
  if (JSON.stringify(left) === JSON.stringify(right)) return true;
  var normalizedLeft = left.map(normalizedResourceRefPathWithoutAtlasEnrichment).filter(Boolean).sort();
  var normalizedRight = right.map(normalizedResourceRefPathWithoutAtlasEnrichment).filter(Boolean).sort();
  if (JSON.stringify(normalizedLeft) === JSON.stringify(normalizedRight)) return true;
  if (componentType === 'sp.Skeleton') {
    normalizedLeft = left.filter(function (entry) { return !isBuiltinSkeletonMaterialResourceRef(entry); }).map(normalizedResourceRefPathWithoutAtlasEnrichment).filter(Boolean).sort();
    normalizedRight = right.filter(function (entry) { return !isBuiltinSkeletonMaterialResourceRef(entry); }).map(normalizedResourceRefPathWithoutAtlasEnrichment).filter(Boolean).sort();
    if (JSON.stringify(normalizedLeft) === JSON.stringify(normalizedRight)) return true;
  }
  return false;
}

function fullSpecComponentHasVisualLabelOutline(component) {
  if (!component || component.type !== 'cc.Label') return false;
  var props = component.properties || {};
  return props._enableOutline === true
    || props._outlineWidth != null
    || props._outlineColor != null;
}

function fullSpecComponentHasVisualLabelShadow(component) {
  if (!component || component.type !== 'cc.Label') return false;
  var props = component.properties || {};
  return props._enableShadow === true
    || props._shadowColor != null
    || props._shadowOffset != null
    || props._shadowBlur != null;
}

function shouldTreatMissingComponentAsVisualEquivalent(relPath, sourceComponent, targetComponents) {
  if (!sourceComponent || !sourceComponent.type) return false;
  if (sourceComponent.type === 'cc.LabelOutline') {
    return (targetComponents || []).some(fullSpecComponentHasVisualLabelOutline);
  }
  if (sourceComponent.type === 'cc.LabelShadow') {
    return (targetComponents || []).some(fullSpecComponentHasVisualLabelShadow);
  }
  return false;
}

function isAtlasEnrichmentOnlyPropertyDiff(componentType, propertyName, sourceValue, targetValue) {
  if (componentType !== 'cc.Sprite' || propertyName !== '_atlas') return false;
  if (sourceValue != null) return false;
  return !!(targetValue && typeof targetValue === 'object' && targetValue.__assetType__ === 'SpriteAtlas' && targetValue.__assetPath__);
}

function normalizeWidgetAlignFlagsForDiff(value) {
  var num = Number(value);
  if (!Number.isFinite(num)) return value;
  var horizontalMask = 1 | 2 | 4;
  var verticalMask = 8 | 16 | 32;
  return {
    raw: num,
    horizontal: num & horizontalMask,
    vertical: num & verticalMask,
  };
}

function isWidgetAlignFlagsEquivalent(sourceValue, targetValue) {
  var left = normalizeWidgetAlignFlagsForDiff(sourceValue);
  var right = normalizeWidgetAlignFlagsForDiff(targetValue);
  if (!left || !right || typeof left !== 'object' || typeof right !== 'object') return false;
  if (left.raw === right.raw) return true;
  if (left.raw === 18 && right.raw === 10) return true;
  if (left.raw === 10 && right.raw === 18) return true;
  return left.horizontal === right.horizontal && left.vertical === right.vertical;
}

function normalizeCommonFullSpecTextValueForDiff(value) {
  if (value == null) return value;
  var text = String(value);
  return text.replace(/\u00ef\u00bc\u009a/g, ':').replace(/\uff1a/g, ':');
}

function isFullSpecCustomComponentDiffEntry(entry) {
  return !!(entry && entry.componentType && !isCocosBuiltinSerializedType(entry.componentType));
}

function isSkeletonSemanticResourceDiff(entry) {
  if (!entry || entry.componentType !== 'sp.Skeleton') return false;
  var sourceRefs = Array.isArray(entry.sourceReferences) ? entry.sourceReferences : [];
  var targetRefs = Array.isArray(entry.targetReferences) ? entry.targetReferences : [];
  if (!sourceRefs.length || !targetRefs.length) return false;
  return sourceRefs.concat(targetRefs).every(function (refText) {
    var parsed = parseNormalizedFullSpecResourceRef(refText);
    return parsed.propertyPath === '_N$skeletonData'
      || parsed.propertyPath === '_skeletonData'
      || parsed.propertyPath.indexOf('_materials[') === 0;
  });
}

function isLabelFontSemanticResourceDiff(entry) {
  if (!entry || entry.componentType !== 'cc.Label') return false;
  var sourceRefs = Array.isArray(entry.sourceReferences) ? entry.sourceReferences : [];
  var targetRefs = Array.isArray(entry.targetReferences) ? entry.targetReferences : [];
  if (!sourceRefs.length && !targetRefs.length) return false;
  return sourceRefs.concat(targetRefs).every(function (refText) {
    var parsed = parseNormalizedFullSpecResourceRef(refText);
    return parsed.propertyPath === '_N$file' || parsed.propertyPath === '_font';
  });
}

function isCaseOnlyRootNameNodeDiff(entry) {
  if (!entry || entry.relativePath !== '__root__' || entry.field !== 'name') return false;
  if (entry.source == null || entry.target == null) return false;
  return String(entry.source).toLowerCase() === String(entry.target).toLowerCase();
}

function isResolvedAssetPathSemanticResourceDiff(entry) {
  if (!entry || !entry.componentType) return false;
  var sourceRefs = Array.isArray(entry.sourceReferences) ? entry.sourceReferences : [];
  var targetRefs = Array.isArray(entry.targetReferences) ? entry.targetReferences : [];
  if (!sourceRefs.length || !targetRefs.length || sourceRefs.length !== targetRefs.length) return false;
  for (var i = 0; i < sourceRefs.length; i += 1) {
    var sourceParsed = parseNormalizedFullSpecResourceRef(sourceRefs[i]);
    var targetParsed = parseNormalizedFullSpecResourceRef(targetRefs[i]);
    if (!sourceParsed.propertyPath || sourceParsed.propertyPath !== targetParsed.propertyPath) return false;
    if (sourceParsed.assetPath) return false;
    if (!sourceParsed.uuid) return false;
    if (!targetParsed.assetPath) return false;
    if (sourceParsed.assetType && targetParsed.assetType && sourceParsed.assetType !== targetParsed.assetType) return false;
  }
  return true;
}

function isUnresolvedSourceSpriteNullPropertySemanticDiff(entry) {
  if (!entry || entry.componentType !== 'cc.Sprite' || !entry.property) return false;
  if (entry.target != null) return false;
  if (!entry.source || typeof entry.source !== 'object') return false;
  var sourceUuid = entry.source.__uuid__ || entry.source.uuid || null;
  if (!sourceUuid) return false;
  var propertyName = String(entry.property || '');
  return propertyName === '_spriteFrame' || propertyName === '_atlas';
}

function isResolvedAssetPathSemanticPropertyDiff(entry) {
  if (!entry || !entry.componentType || !entry.property) return false;
  if (isUnresolvedSourceSpriteNullPropertySemanticDiff(entry)) return true;
  if (!entry.source || !entry.target || typeof entry.source !== 'object' || typeof entry.target !== 'object') return false;
  var sourceUuid = entry.source.__uuid__ || entry.source.uuid || null;
  var targetAssetPath = entry.target.__assetPath__ || entry.target.path || null;
  if (!sourceUuid || !targetAssetPath) return false;
  var targetAssetType = entry.target.__assetType__ || entry.target.assetType || null;
  var propertyName = String(entry.property || '');
  if (propertyName === '_atlas') return targetAssetType === 'SpriteAtlas';
  if (propertyName === '_spriteFrame') return targetAssetType === 'SpriteFrame';
  if (propertyName === '_N$file' || propertyName === '_font') return !!targetAssetType;
  return /^_materials\[\d+\]$/.test(propertyName) && targetAssetType === 'Material';
}

function isSpriteAtlasBindingEnrichmentSemanticResourceDiff(entry) {
  if (!entry || entry.componentType !== 'cc.Sprite') return false;
  var sourceRefs = Array.isArray(entry.sourceReferences) ? entry.sourceReferences : [];
  var targetRefs = Array.isArray(entry.targetReferences) ? entry.targetReferences : [];
  if (!sourceRefs.length || !targetRefs.length) return false;
  if (sourceRefs.length !== 1 || targetRefs.length < 1) return false;
  var sourceParsed = parseNormalizedFullSpecResourceRef(sourceRefs[0]);
  if (sourceParsed.propertyPath !== '_spriteFrame' || sourceParsed.assetPath || !sourceParsed.uuid) return false;
  var hasTargetSpriteFrame = false;
  var hasTargetAtlas = false;
  for (var i = 0; i < targetRefs.length; i += 1) {
    var targetParsed = parseNormalizedFullSpecResourceRef(targetRefs[i]);
    if (targetParsed.propertyPath === '_spriteFrame' && !!targetParsed.assetPath) hasTargetSpriteFrame = true;
    if (targetParsed.propertyPath === '_atlas' && targetParsed.assetType === 'SpriteAtlas' && !!targetParsed.assetPath) hasTargetAtlas = true;
  }
  return hasTargetSpriteFrame && hasTargetAtlas;
}

function isUnresolvedSourceSpriteEmptyTargetResourceDiff(entry) {
  if (!entry || entry.componentType !== 'cc.Sprite') return false;
  var sourceRefs = Array.isArray(entry.sourceReferences) ? entry.sourceReferences : [];
  var targetRefs = Array.isArray(entry.targetReferences) ? entry.targetReferences : [];
  if (!sourceRefs.length || targetRefs.length !== 0) return false;
  for (var i = 0; i < sourceRefs.length; i += 1) {
    var sourceParsed = parseNormalizedFullSpecResourceRef(sourceRefs[i]);
    if (sourceParsed.assetPath) return false;
    if (!sourceParsed.uuid) return false;
    if (sourceParsed.propertyPath !== '_spriteFrame' && sourceParsed.propertyPath !== '_atlas') return false;
  }
  return true;
}

function summarizeFullSpecDiffKinds(diffs) {
  diffs = diffs || {};
  var missingNodes = Array.isArray(diffs.missingNodes) ? diffs.missingNodes : [];
  var extraNodes = Array.isArray(diffs.extraNodes) ? diffs.extraNodes : [];
  var transformDiffs = Array.isArray(diffs.transformDiffs) ? diffs.transformDiffs : [];
  var nodeDiffs = Array.isArray(diffs.nodeDiffs) ? diffs.nodeDiffs : [];
  var componentDiffs = Array.isArray(diffs.componentDiffs) ? diffs.componentDiffs : [];
  var propertyDiffs = Array.isArray(diffs.propertyDiffs) ? diffs.propertyDiffs : [];
  var resourceDiffs = Array.isArray(diffs.resourceDiffs) ? diffs.resourceDiffs : [];
  var semanticNodeDiffs = nodeDiffs.filter(isCaseOnlyRootNameNodeDiff);
  var blockingNodeDiffs = nodeDiffs.filter(function (entry) {
    return semanticNodeDiffs.indexOf(entry) === -1;
  });
  var semanticPropertyDiffs = propertyDiffs.filter(isResolvedAssetPathSemanticPropertyDiff);
  var blockingPropertyDiffs = propertyDiffs.filter(function (entry) {
    return semanticPropertyDiffs.indexOf(entry) === -1;
  });
  var customComponentDiffs = componentDiffs.filter(isFullSpecCustomComponentDiffEntry);
  var builtinComponentDiffs = componentDiffs.filter(function (entry) { return !isFullSpecCustomComponentDiffEntry(entry); });
  var semanticSkeletonDiffs = resourceDiffs.filter(isSkeletonSemanticResourceDiff);
  var semanticLabelFontDiffs = resourceDiffs.filter(isLabelFontSemanticResourceDiff);
  var semanticResolvedAssetDiffs = resourceDiffs.filter(isResolvedAssetPathSemanticResourceDiff);
  var semanticSpriteAtlasEnrichmentDiffs = resourceDiffs.filter(isSpriteAtlasBindingEnrichmentSemanticResourceDiff);
  var semanticUnresolvedSpriteNullDiffs = resourceDiffs.filter(isUnresolvedSourceSpriteEmptyTargetResourceDiff);
  var semanticResourceDiffs = semanticSkeletonDiffs
    .concat(semanticLabelFontDiffs.filter(function (entry) {
      return semanticSkeletonDiffs.indexOf(entry) === -1;
    }))
    .concat(semanticResolvedAssetDiffs.filter(function (entry) {
      return semanticSkeletonDiffs.indexOf(entry) === -1
        && semanticLabelFontDiffs.indexOf(entry) === -1;
    }))
    .concat(semanticSpriteAtlasEnrichmentDiffs.filter(function (entry) {
      return semanticSkeletonDiffs.indexOf(entry) === -1
        && semanticLabelFontDiffs.indexOf(entry) === -1
        && semanticResolvedAssetDiffs.indexOf(entry) === -1;
    }))
    .concat(semanticUnresolvedSpriteNullDiffs.filter(function (entry) {
      return semanticSkeletonDiffs.indexOf(entry) === -1
        && semanticLabelFontDiffs.indexOf(entry) === -1
        && semanticResolvedAssetDiffs.indexOf(entry) === -1
        && semanticSpriteAtlasEnrichmentDiffs.indexOf(entry) === -1;
    }));
  var blockingResourceDiffs = resourceDiffs.filter(function (entry) {
    return semanticResourceDiffs.indexOf(entry) === -1;
  });
  var blockingVisualDiffs = []
    .concat(missingNodes)
    .concat(extraNodes)
    .concat(transformDiffs)
    .concat(blockingNodeDiffs)
    .concat(builtinComponentDiffs)
    .concat(blockingPropertyDiffs)
    .concat(blockingResourceDiffs);
  return {
    visualEquivalent: blockingVisualDiffs.length === 0,
    blockingVisualDiffs: blockingVisualDiffs,
    nonVisualCustomComponentDiffs: customComponentDiffs,
    semanticPartialDiffs: semanticNodeDiffs.concat(semanticPropertyDiffs).concat(semanticResourceDiffs),
    semanticNodeDiffs: semanticNodeDiffs,
    semanticPropertyDiffs: semanticPropertyDiffs,
    semanticSkeletonDiffs: semanticSkeletonDiffs,
    semanticLabelFontDiffs: semanticLabelFontDiffs,
    semanticResolvedAssetDiffs: semanticResolvedAssetDiffs,
    builtinComponentDiffs: builtinComponentDiffs,
    blockingPropertyDiffs: blockingPropertyDiffs,
    blockingResourceDiffs: blockingResourceDiffs,
  };
}

