      arguments: { view: view, checkScreenshot: false, keyNodes: keyNodes.length ? keyNodes : ['Canvas'], checkBounds: true, canvasId: canvasId },
      requiredEvidence: ['canvas resolved', 'node bounding boxes or layout details', 'out-of-bounds failure when applicable'],
