  sprite_tint_glow: { status: 'supported', renderer: 'cc.Sprite', category: 'sprite-color', aliases: [], properties: ['tintColor', 'glowColor', 'glowStrength'], evidence: 'Preset source, property parse, material property write/readback, and Sprite assignment are covered by material-shader-boundary.' },
  outline: { status: 'supported', renderer: 'cc.Sprite', category: 'sprite-outline', aliases: ['sprite_outline'], properties: ['outlineColor', 'outlineWidth', 'textureSize'], evidence: 'Preset source can be generated and assigned through manage_visual_effect; runtime compile remains environment-dependent.' },
