  sprite_sweep_shine: { status: 'supported', renderer: 'cc.Sprite', category: 'sprite-highlight', aliases: ['sprite_mirror_shine', 'sweep_shine'], properties: ['shineColor', 'shineWidth', 'shineIntensity', 'shineAngle', 'shineOffset'], evidence: 'Preset source can be generated and assigned through manage_visual_effect; runtime compile remains environment-dependent.' },
  sprite_water_ripple: { status: 'supported', renderer: 'cc.Sprite', category: 'sprite-distortion', aliases: ['water_ripple', 'ripple'], properties: ['rippleCenter', 'rippleRadius', 'rippleWidth', 'rippleStrength', 'ripplePhase'], evidence: 'Preset source can be generated and assigned through manage_visual_effect; runtime compile remains environment-dependent.' },
