    if (!actual.components || actual.components.indexOf('cc.Button') < 0) add('component', 'Expected cc.Button component', { components: actual.components || [] });
    if (!actual.components || actual.components.indexOf('cc.Sprite') < 0) add('component', 'Expected cc.Sprite component on button', { components: actual.components || [] });
