    if (!actual.components || actual.components.indexOf('cc.Sprite') < 0) add('component', 'Expected cc.Sprite component on toggle', { components: actual.components || [] });
    if (!actual.spriteFrameUuid) add('toggle.normalSprite', 'Expected Toggle/Sprite normalSprite SpriteFrame binding', { spriteFrameUuid: actual.spriteFrameUuid || null });
    var toggleActual = actual.toggle || {};
