          compareNumber('scrollView.layout.startAxis', expected.scrollView.layout.startAxis, contentNode.layout.startAxis);
          compareBoolean('scrollView.layout.affectedByScale', expected.scrollView.layout.affectedByScale, contentNode.layout.affectedByScale);
          compareArray('scrollView.layout.spacing', expected.scrollView.layout.spacing, [contentNode.layout.spacingX || 0, contentNode.layout.spacingY || 0]);
          compareArray('scrollView.layout.cellSize', expected.scrollView.layout.cellSize, contentNode.layout.cellSize);
