        path: currentPath,
        name: node.name || 'Node',
        components: node.components || [],
        spriteFrameUuid: node.spriteFrameUuid || null,
        targetPath: node.toggle && node.toggle.targetPath || null,
        checkMarkPath: node.toggle && node.toggle.checkMarkPath || null,
