          path: dbPath + '/' + encodeURIComponent(subAssetName),
          parentPath: dbPath,
          fspath: assetFspath,
          metaPath: full,
          type: sm.importer || sm.type || key,
          importer: sm.importer || null,
          subAsset: true,
          subAssetName: subAssetName,
          subAssetId: sm.id || key,
