    spriteframe: 'SpriteFrame',
    'sprite-frame': 'SpriteFrame',
    spriteatlas: 'SpriteAtlas',
    atlas: 'SpriteAtlas',
    texture: 'Texture2D',
    texture2d: 'Texture2D',
    image: 'Texture2D',
    material: 'Material',
    effect: 'Effect',
    font: 'Font',
    bitmapfont: 'Font',
    audio: 'AudioClip',
    audioclip: 'AudioClip',
    prefab: 'Prefab',
    animation: 'AnimationClip',
    animationclip: 'AnimationClip',
    clip: 'AnimationClip',
    scene: 'Scene',
    tilemap: 'TileMap',
    tiledmap: 'TileMap',
    tmx: 'TileMap',
    tileset: 'Tileset',
    particle: 'ParticleAsset',
    particleasset: 'ParticleAsset',
    plist: 'ParticleAsset',
    skeleton: 'SkeletonData',
    skeletondata: 'SkeletonData',
    spinedata: 'SkeletonData',
    spineskeleton: 'SkeletonData',
