  if (expectedType === actualType) return true;
  if (expectedType === 'SpriteFrame' && actualType === 'Texture2D') return false;
  if (expectedType === 'SpriteAtlas' && actualType === 'SpriteFrame') return false;
  if (expectedType === 'ParticleAsset' && ['ParticleAsset', 'Texture2D'].indexOf(actualType) !== -1) return true;
  if (expectedType === 'TileMap' && ['TileMap', 'Tileset'].indexOf(actualType) !== -1) return true;
