      componentType: normalized,
      className: normalized,
      status: 'deprecated',
      deprecated: true,
      replacementComponent: deprecatedLabelEffect.replacementComponent,
      replacementProperties: deprecatedLabelEffect.replacementProperties,
      message: deprecatedLabelEffect.message,
      properties: {},
      methods: [],
      replacementSchema: replacement,
      source: 'builtin-fallback',
