    var refOk = typeof value === 'string' || (isPlainObject(value) && (value.uuid || value.path || value.__uuid__ || value.__id__ !== undefined));
    if (!refOk) return componentPreflightDiagnostic('wrong_shape', componentType, key, componentType + '.' + key + ' expects ' + expectedType + ' reference', { expectedType: expectedType, actualType: typeof value });
