          var current = editorState && editorState.current || null;
          var dirtyBefore = await editorHelpers.querySceneDirtyState();
          var smokeRoot = args.smokeRoot || 'db://assets/__mcp_smoke__/prefab-ipc/';
          var prefabPath = smokeRoot.replace(/\/+$/, '') + '/Probe_' + probeStartedAt + '.prefab';
          var sourceNodeId = null;
