register({
  name: 'diagnose_current_prefab_serialize',
  description: 'Read-only diagnostic for current prefab edit context serialization through scene-side Cocos serializers. Does not save, close, open, or switch assets.',
  inputSchema: {
    type: 'object',
    properties: {
      rootUuid: { type: 'string' },
      nodeUuid: { type: 'string' },
      prefabUuid: { type: 'string' },
      returnContent: { type: 'boolean' },
    },
  },
  execute: async function (args) {
    args = args || {};
    var dump = await editorHelpers.queryCurrentPrefabEditDump();
    var serialize = await commandQueue.callSceneScript('serialize-current-prefab-edit-context', {
      rootUuid: args.rootUuid || dump && dump.rootUuid || null,
      nodeUuid: args.nodeUuid || dump && dump.nodeUuid || null,
      prefabUuid: args.prefabUuid || dump && (dump.prefabUuid || dump.assetUuid) || null,
      returnContent: args.returnContent === true,
    }, 8000);
    if (serialize && args.returnContent !== true) delete serialize.content;
    return {
      ok: !!(serialize && serialize.ok),
      success: !!(serialize && serialize.ok),
      status: serialize && serialize.ok ? 'passed' : 'failed',
      prefabDump: dump,
      serialize: serialize,
      dirty: await editorHelpers.querySceneDirtyState(),
    };
  },
});

register({
  name: 'prefab_safe_edit_plan',
  description: 'Return a dialog-safe prefab edit plan and capability boundary without opening, closing, switching, or mutating prefab assets.',
  inputSchema: {
    type: 'object',
    properties: {
      path: { type: 'string' },
      prefabPath: { type: 'string' },
      intendedEdits: { type: 'array' },
      includeWorkflowTemplates: { type: 'boolean' },
    },
  },
  execute: async function (args) {
    args = args || {};
    var prefabPath = args.path || args.prefabPath || null;
    var intendedEdits = Array.isArray(args.intendedEdits) ? args.intendedEdits : [];
    var supportedSteps = [
      { step: 'create_from_scene_node', tool: 'manage_prefab', action: 'create', supported: true, note: 'Creates or overwrites a prefab from an existing scene node through Editor/AssetDB APIs.' },
      { step: 'asset_refresh', tool: 'manage_asset', action: 'refresh', supported: true, note: 'Refreshes the prefab asset path without opening editor tabs.' },
      { step: 'asset_info_readback', tool: 'manage_asset', action: 'get_info', supported: true, note: 'Reads AssetDB UUID/path evidence.' },
      { step: 'static_validation', tool: 'validate_prefab_static_v2', supported: true, note: 'Validates serialized prefab structure and references without opening the prefab.' },
      { step: 'in_place_validation', tool: 'prefab_reopen_validate', supported: true, note: 'Performs save-when-safe plus static/in-place validation; close/reopen remains suppressed.' },
      { step: 'instantiate_for_scene_layout', tool: 'manage_prefab', action: 'instantiate', supported: true, note: 'Instantiates a prefab into the current scene for layout/preview when live scene context is safe.' },
    ];
    var blockedSteps = [
      { step: 'open_prefab_for_edit', tool: 'manage_prefab', action: 'open', status: 'blocked', missingCapability: 'mcp_safe_prefab_editor_context_open', interactivePromptSuppressed: true, reason: 'Opening a prefab can switch editor assets and show dirty-save dialogs; MCP cannot yet prove active prefab identity plus dirty state.' },
      { step: 'close_prefab_edit_mode', tool: 'manage_prefab', action: 'close', status: 'partial-clean-only', note: 'Only already-clean prefab edit contexts are currently supported for unattended close. Dirty prefab close/save/discard remains blocked until a non-popup path is proven.' },
      { step: 'edit_prefab_nodes_in_hidden_context', status: 'blocked', missingCapability: 'prefab_node_mutation_without_editor_context_switch', interactivePromptSuppressed: true, reason: 'MCP can create prefab assets from scene nodes and validate statically, but cannot yet mutate arbitrary prefab node trees without a proven non-interactive editor context.' },
    ];
    var workflowTemplates = null;
    if (args.includeWorkflowTemplates !== false) {
      workflowTemplates = loadWorkflows().listTemplates().filter(function (template) {
        return /^prefab_/.test(String(template.name || ''));
      });
    }
    var assetInfo = null;
    var staticValidation = null;
    if (prefabPath) {
      try { assetInfo = await call('manage_asset', { action: 'get_info', path: prefabPath, silent: true }); } catch (assetInfoError) { assetInfo = { ok: false, error: assetInfoError.message || String(assetInfoError) }; }
      try { staticValidation = await call('validate_prefab_static_v2', { path: prefabPath, includeTree: false, includeGraph: true, strict: false }); } catch (staticValidationError) { staticValidation = { ok: false, error: staticValidationError.message || String(staticValidationError) }; }
    }
    return {
      ok: true,
      status: 'partial',
      prefabPath: prefabPath,
      intendedEditCount: intendedEdits.length,
      intendedEdits: intendedEdits,
      supportedSteps: supportedSteps,
      blockedSteps: blockedSteps,
      workflowTemplates: workflowTemplates,
      assetInfo: assetInfo,
      staticValidation: staticValidation,
      interactivePromptSuppressed: true,
      noPrefabOpenCloseOrSwitch: true,
      missingCapability: 'prefab_node_mutation_without_editor_context_switch',
      nextSuggestedFix: 'Add a proven non-interactive prefab edit-context identity + dirty-state readback before enabling arbitrary prefab node/component mutation.',
    };
  },
});

