register({
  name: 'validate_prefab_editor_openable',
  description: 'Validate that a prefab is statically Creator-openable, then safely open it in the editor, read back its root/hierarchy, inspect fresh console output, and guarded-close it without asking the user to save.',
  inputSchema: {
    type: 'object',
    properties: {
      path: { type: 'string' },
      prefabPath: { type: 'string' },
      strict: { type: 'boolean' },
      strictEditorOpenable: { type: 'boolean' },
      failOnWarnings: { type: 'boolean' },
      readConsole: { type: 'boolean' },
      consoleCount: { type: 'number' },
      sinceTs: { type: 'number' },
      startedAt: { type: 'number' },
      closeAfterOpen: { type: 'boolean' },
      captureScreenshot: { type: 'boolean' },
      screenshotPath: { type: 'string' },
    },
  },
  execute: async function (args) {
    args = args || {};
    var prefabPath = args.path || args.prefabPath;
    if (!prefabPath) throw new Error('validate_prefab_editor_openable requires path or prefabPath');
    var startedAt = Number(args.sinceTs || args.startedAt || Date.now());
    var steps = [];
    function blocked(reason, extra) {
      return Object.assign({
        ok: false,
        success: false,
        status: 'blocked',
        blocked: true,
        interactivePromptSuppressed: true,
        path: prefabPath,
        reason: reason,
        steps: steps,
      }, extra || {});
    }
    function failed(reason, extra) {
      return Object.assign({
        ok: false,
        success: false,
        status: 'failed',
        path: prefabPath,
        reason: reason,
        steps: steps,
      }, extra || {});
    }

    var staticValidation;
    try {
      staticValidation = await call('validate_prefab_static_v2', {
        path: prefabPath,
        strict: args.strict !== false,
        includeTree: false,
        includeGraph: true,
        editorOpenable: true,
        strictEditorOpenable: args.strictEditorOpenable !== false,
      });
      steps.push({ step: 'validate_prefab_static_v2_editor_openable', status: staticValidation.status, editorOpenable: staticValidation.checks && staticValidation.checks.editorOpenable || null });
    } catch (staticError) {
      return failed('Static Creator-openable validation failed before editor open.', {
        error: staticError.message || String(staticError),
        missingCapability: 'prefab_static_creator_openable_metadata',
      });
    }

    var preflight = await call('ensure_no_dialog_risk', { operation: 'open_prefab', path: prefabPath, sinceTs: startedAt, readConsole: args.readConsole !== false });
    steps.push({ step: 'ensure_no_dialog_risk_open_prefab', result: preflight });
    if (preflight && (preflight.blocked || preflight.status === 'blocked' || preflight.interactivePromptSuppressed)) {
      return blocked('Opening prefab is not dialog-safe from the current editor context.', {
        missingCapability: preflight.missingCapability || 'mcp_safe_prefab_editor_context_open',
        preflight: preflight,
      });
    }

    var openResult = await call('manage_prefab', { action: 'open', path: prefabPath, sinceTs: startedAt, readConsole: args.readConsole !== false });
    steps.push({ step: 'manage_prefab_open', result: openResult });
    if (!openResult || openResult.blocked || openResult.status === 'blocked') {
      return blocked('Prefab open was blocked by MCP safety guard.', {
        missingCapability: openResult && openResult.missingCapability || 'mcp_safe_prefab_editor_context_open',
        openResult: openResult || null,
      });
    }
    if (openResult.ok === false || openResult.success === false) {
      return failed('Prefab open failed.', { openResult: openResult });
    }

    var hierarchy = await call('get_scene_hierarchy', { depth: 6, includeDetails: false, maxChildren: 240 });
    steps.push({ step: 'get_scene_hierarchy_after_open', root: hierarchy && hierarchy.name || null, uuid: hierarchy && hierarchy.uuid || null });
    if (!hierarchy || !hierarchy.uuid) {
      return failed('Opened prefab hierarchy readback failed.', {
        missingCapability: 'prefab_editor_hierarchy_readback',
        hierarchy: hierarchy || null,
      });
    }

    var dump = null;
    try {
      dump = await editorHelpers.queryCurrentPrefabEditDump();
      steps.push({ step: 'query_current_prefab_edit_dump', ok: dump && dump.ok, rootUuid: dump && dump.rootUuid || null, nodeName: dump && dump.nodeName || null });
    } catch (dumpError) {
      dump = { ok: false, error: dumpError.message || String(dumpError) };
      steps.push({ step: 'query_current_prefab_edit_dump', ok: false, error: dump.error });
    }
    var inferredRoot = inferPrefabEditRootFromHierarchy(hierarchy, prefabPath, dump);
    steps.push({
      step: 'infer_prefab_edit_root_from_hierarchy',
      ok: inferredRoot.ok,
      method: inferredRoot.method,
      rootUuid: inferredRoot.node && (inferredRoot.node.uuid || inferredRoot.node.id || inferredRoot.node.nodeId) || null,
      rootName: inferredRoot.node && inferredRoot.node.name || null,
      candidateCount: inferredRoot.candidateCount || 0,
    });
    if (!inferredRoot || inferredRoot.ok !== true || !inferredRoot.node) {
      return failed('Opened prefab did not expose a readable prefab edit root through dump or hierarchy fallback.', {
        missingCapability: 'current_prefab_edit_root_readback',
        prefabDump: dump || null,
        hierarchy: { name: hierarchy && hierarchy.name || null, uuid: hierarchy && hierarchy.uuid || null },
      });
    }

    var screenshot = null;
    var screenshotRequested = args.captureScreenshot === true || !!args.screenshotPath;
    if (screenshotRequested) {
      try {
        screenshot = await call('capture_screenshot', args.screenshotPath ? { savePath: args.screenshotPath } : {});
        steps.push({
          step: 'capture_screenshot_after_open',
          ok: screenshot && screenshot.ok !== false,
          savedPath: screenshot && (screenshot.savedPath || screenshot.saved || null) || null,
          source: screenshot && screenshot.source || null,
          title: screenshot && screenshot.title || null,
        });
      } catch (screenshotError) {
        screenshot = { ok: false, error: screenshotError.message || String(screenshotError) };
        steps.push({ step: 'capture_screenshot_after_open', ok: false, error: screenshot.error });
      }
      var screenshotSavedPath = screenshot && (screenshot.savedPath || screenshot.saved || null) || null;
      if (!screenshot || screenshot.ok === false || !screenshotSavedPath || !fs.existsSync(String(screenshotSavedPath))) {
        return failed('Prefab open screenshot was requested but no screenshot artifact was produced.', {
          missingCapability: 'prefab_editor_open_screenshot_artifact',
          screenshot: screenshot,
          staticValidation: staticValidation,
          openResult: openResult,
          prefabDump: dump,
          inferredRoot: {
            method: inferredRoot.method,
            uuid: inferredRoot.node && (inferredRoot.node.uuid || inferredRoot.node.id || inferredRoot.node.nodeId) || null,
            name: inferredRoot.node && inferredRoot.node.name || null,
          },
          hierarchy: { name: hierarchy && hierarchy.name || null, uuid: hierarchy && hierarchy.uuid || null },
        });
      }
      var screenshotProof = screenshotHasPrefabSpecificVisualProof(screenshot, prefabPath);
      steps.push({
        step: 'validate_prefab_visual_screenshot_proof',
        ok: screenshotProof.ok,
        reason: screenshotProof.reason || null,
        source: screenshotProof.proof && screenshotProof.proof.source || null,
        acceptedSources: screenshotProof.proof && screenshotProof.proof.acceptedSources || [],
      });
      if (!screenshotProof.ok) {
        return blocked('Prefab screenshot could not be proven to show the target prefab visual content.', {
          missingCapability: 'prefab_visual_window_specific_screenshot_proof',
          screenshot: screenshot,
          screenshotProof: screenshotProof,
          staticValidation: staticValidation,
          openResult: openResult,
          prefabDump: dump,
          inferredRoot: {
            method: inferredRoot.method,
            uuid: inferredRoot.node && (inferredRoot.node.uuid || inferredRoot.node.id || inferredRoot.node.nodeId) || null,
            name: inferredRoot.node && inferredRoot.node.name || null,
          },
          hierarchy: { name: hierarchy && hierarchy.name || null, uuid: hierarchy && hierarchy.uuid || null },
        });
      }
    }

    var closeResult = null;
    if (args.closeAfterOpen !== false && openResult.opened !== false) {
      closeResult = await call('manage_prefab', { action: 'close', path: prefabPath, sinceTs: startedAt, readConsole: args.readConsole !== false });
      steps.push({ step: 'manage_prefab_close', result: closeResult });
      if (!closeResult || closeResult.blocked || closeResult.status === 'blocked') {
        return blocked('Prefab close was blocked by MCP safety guard after successful open/readback.', {
          missingCapability: closeResult && closeResult.missingCapability || 'mcp_safe_prefab_editor_context_close',
          closeResult: closeResult || null,
        });
      }
      if (closeResult.ok === false || closeResult.success === false) {
        return failed('Prefab guarded close failed after successful open/readback.', { closeResult: closeResult });
      }
    } else {
      steps.push({ step: 'manage_prefab_close', skipped: true, reason: openResult.opened === false ? 'prefab_was_already_open' : 'closeAfterOpen_false' });
    }

    var consoleErrors = [];
    var consoleWarnings = [];
    try { consoleErrors = await call('read_console', { level: 'error', sinceTs: startedAt, count: args.consoleCount || 80 }); } catch (consoleError) { consoleErrors = [{ level: 'error', message: consoleError.message || String(consoleError) }]; }
    try { consoleWarnings = await call('read_console', { level: 'warn', sinceTs: startedAt, count: args.consoleCount || 80 }); } catch (consoleWarnError) { consoleWarnings = [{ level: 'warn', message: consoleWarnError.message || String(consoleWarnError) }]; }
    steps.push({ step: 'read_console_since_operation', errorCount: consoleErrors.length, warningCount: consoleWarnings.length });
    consoleErrors = (consoleErrors || []).filter(function (entry) {
      var text = String(entry && (entry.message || entry.msg || entry.text || entry.raw || '')).toLowerCase();
      return text.indexOf('failed verify_console_baseline: sincets or startedat is required') === -1;
    });
    if (consoleErrors.length || (args.failOnWarnings === true && consoleWarnings.length)) {
      return failed('Fresh console entries were found while validating prefab editor openability.', {
        consoleErrorCount: consoleErrors.length,
        consoleWarningCount: consoleWarnings.length,
        recentConsoleErrors: consoleErrors,
        recentConsoleWarnings: consoleWarnings,
      staticValidation: staticValidation,
      openResult: openResult,
      closeResult: closeResult,
      prefabDump: dump,
      inferredRoot: {
        method: inferredRoot.method,
        uuid: inferredRoot.node && (inferredRoot.node.uuid || inferredRoot.node.id || inferredRoot.node.nodeId) || null,
        name: inferredRoot.node && inferredRoot.node.name || null,
      },
      hierarchy: { name: hierarchy && hierarchy.name || null, uuid: hierarchy && hierarchy.uuid || null },
    });
    }

    return {
      ok: true,
      success: true,
      status: 'passed',
      path: prefabPath,
      staticValidation: staticValidation,
      openResult: openResult,
      prefabDump: dump,
      inferredRoot: {
        method: inferredRoot.method,
        uuid: inferredRoot.node && (inferredRoot.node.uuid || inferredRoot.node.id || inferredRoot.node.nodeId) || null,
        name: inferredRoot.node && inferredRoot.node.name || null,
      },
      hierarchy: { name: hierarchy && hierarchy.name || null, uuid: hierarchy && hierarchy.uuid || null },
      closeResult: closeResult,
      screenshotRequested: screenshotRequested,
      screenshotPath: screenshot && (screenshot.savedPath || screenshot.saved || null) || null,
      screenshotExists: !!(screenshot && (screenshot.savedPath || screenshot.saved || null) && fs.existsSync(String(screenshot.savedPath || screenshot.saved || ''))),
      screenshot: screenshot,
      consoleErrorCount: consoleErrors.length,
      consoleWarningCount: consoleWarnings.length,
      recentConsoleErrors: consoleErrors,
      recentConsoleWarnings: consoleWarnings,
      noManualSaveRequested: true,
      interactivePromptSuppressed: false,
      steps: steps,
    };
  },
});

