register({
  name: 'manage_asset',
  description: 'Asset operations: create files/directories, delete, move, copy, get_info, refresh.',
  inputSchema: {
    type: 'object',
    properties: {
      action: { type: 'string', enum: ['create', 'update', 'write', 'delete', 'move', 'copy', 'get_info', 'refresh'] },
      path: { type: 'string' },
      content: { type: 'string' },
      destPath: { type: 'string' },
      overwrite: { type: 'boolean' },
      force: { type: 'boolean' },
      missingOk: { type: 'boolean' },
      silent: { type: 'boolean' },
      sinceTs: { type: 'number' },
      startedAt: { type: 'number' },
      readConsole: { type: 'boolean' },
    },
    required: ['action'],
  },
  execute: async function (args) {
    var url = args.path;
    var evidenceStartedAt = Number(args.sinceTs || args.startedAt || Date.now());
    switch (args.action) {
      case 'create':
        if (!url) throw new Error('path is required');
        var looksLikeDirectory = /\/$/.test(String(url)) || !path.extname(String(url).replace(/\/+$/, ''));
        if (looksLikeDirectory) {
          return await withOperationEvidence(evidenceStartedAt, async function () {
            var normalizedDirUrl = String(url).replace(/\/+$/, '');
            if (normalizedDirUrl !== 'db://assets' && normalizedDirUrl.indexOf('db://assets/') !== 0) {
              throw new Error('Only db://assets directories can be created: ' + url);
            }
            var dirPath = editorHelpers.urlToFspath(String(url).replace(/\/+$/, ''));
            if (!dirPath) throw new Error('Only db://assets directories can be created: ' + url);
            dirPath = assertInsideProject(dirPath, 'manage_asset(action:"create")');
            if (fs.existsSync(dirPath) && !fs.statSync(dirPath).isDirectory()) {
              throw new Error('Path exists and is not a directory: ' + url);
            }
            fs.mkdirSync(dirPath, { recursive: true });
            await editorHelpers.refreshAssetDb(url);
            return { ok: true, path: String(url).replace(/\/+$/, ''), message: 'Directory created: ' + String(url).replace(/\/+$/, '') };
          }, { readConsole: args.readConsole });
        }
        if (String(url).indexOf('db://assets/') !== 0 && String(url) !== 'db://assets') {
          throw new Error('Only project-owned db://assets paths can be created: ' + url);
        }
        assertNotStructuredAssetPath(url, 'manage_asset(action:"create")');
        return await withOperationEvidence(evidenceStartedAt, async function () {
          return await new Promise(function (resolve, reject) {
            assetPatcher.safeCreateAsset(url, args.content || '', function (err, result) {
              if (err) reject(new Error(String(err)));
              else resolve({ ok: true, path: url, message: result || 'Asset created: ' + url });
            });
          });
        }, { readConsole: args.readConsole });

      case 'update':
      case 'write':
        if (!url) throw new Error('path is required');
        if (String(url).indexOf('db://assets/') !== 0) {
          throw new Error('Only project-owned db://assets paths can be updated: ' + url);
        }
        assertNotStructuredAssetPath(url, 'manage_asset(action:"update")');
        return await withOperationEvidence(evidenceStartedAt, async function () {
          return await new Promise(function (resolve, reject) {
            assetPatcher.safeSaveExistingAsset(url, args.content || '', function (err, result) {
              if (err) reject(new Error(String(err)));
              else resolve({ ok: true, path: url, message: result || 'Asset updated: ' + url });
            });
          });
        }, { readConsole: args.readConsole });

      case 'delete':
        if (!url) throw new Error('path is required');
        if (/\.(plist|particle)$/i.test(String(url)) || /\/vfx(\/|$)|\/firework(\/|$)/i.test(String(url))) {
          var hierarchyForDelete = null;
          try {
            hierarchyForDelete = await commandQueue.enqueueSceneOp('get-hierarchy', {
              depth: 30,
              includeDetails: true,
              maxChildren: 800,
            }, 10000);
          } catch (particleDeleteHierarchyError) {
            hierarchyForDelete = null;
          }
          var liveParticleNodes = findNodesWithComponentType(hierarchyForDelete, ['cc.ParticleSystem2D', 'cc.ParticleSystem']);
          if (liveParticleNodes.length > 0 && args.force !== true) {
            return await withOperationEvidence(evidenceStartedAt, async function () {
              return {
                ok: false,
                success: false,
                blocked: true,
                status: 'blocked',
                interactivePromptSuppressed: true,
                path: url,
                reason: 'Deleting particle/VFX assets while live ParticleSystem nodes exist can trigger Cocos asset-watcher null-file errors.',
                liveParticleNodes: liveParticleNodes.map(function (node) {
                  return { uuid: node.uuid || node.id || null, name: node.name || null, path: node.path || null };
                }),
                nextSuggestedFix: 'Delete or unbind live ParticleSystem2D/ParticleSystem scene nodes first, then delete the particle asset folder from a fresh console baseline.',
              };
            }, { readConsole: args.readConsole });
          }
        }
        if (args.missingOk || args.silent) {
          try {
            var exists = await editorHelpers.assetExists(url);
            if (!exists) {
              return await withOperationEvidence(evidenceStartedAt, async function () {
                return { ok: true, skipped: true, path: url, reason: 'Asset already missing' };
              }, { readConsole: args.readConsole });
            }
          } catch (e) {}
        }
        return await withOperationEvidence(evidenceStartedAt, async function () {
          await Editor.Message.request('asset-db', 'delete-asset', url);
          var deleteCleanup = await cleanupMissingSceneNodes({ attempts: 4, delayMs: 250 });
          return { ok: true, path: url, message: 'Asset deleted: ' + url, residualCleanup: deleteCleanup };
        }, { readConsole: args.readConsole });

      case 'move':
        if (!url || !args.destPath) throw new Error('path and destPath are required');
        if (String(url).indexOf('db://assets/') !== 0) throw new Error('Only db://assets sources are supported: ' + url);
        if (String(args.destPath).indexOf('db://assets/') !== 0) throw new Error('Only db://assets destinations are supported: ' + args.destPath);
        assertNotStructuredAssetPath(url, 'manage_asset(action:"move")');
        assertNotStructuredAssetPath(args.destPath, 'manage_asset(action:"move")');
        return await withOperationEvidence(evidenceStartedAt, async function () {
          var moveSrc = editorHelpers.urlToFspath(url);
          if (!moveSrc || !fs.existsSync(moveSrc)) throw new Error('Source not found: ' + url);
          var moveDst = editorHelpers.urlToFspath(args.destPath);
          if (!moveDst) throw new Error('Only db://assets destinations are supported: ' + args.destPath);
          moveDst = assertInsideProject(moveDst, 'manage_asset(action:"move")');
          if (fs.existsSync(moveDst) && !args.overwrite) throw new Error('Destination already exists: ' + args.destPath);
          if (fs.existsSync(moveDst) && args.overwrite) await Editor.Message.request('asset-db', 'delete-asset', args.destPath);
          await Editor.Message.request('asset-db', 'move-asset', url, args.destPath);
          return { ok: true, path: url, destPath: args.destPath, message: 'Asset moved: ' + url + ' -> ' + args.destPath };
        }, { readConsole: args.readConsole });

      case 'copy':
        if (!url || !args.destPath) throw new Error('path and destPath are required');
        if (String(url).indexOf('db://assets/') !== 0) throw new Error('Only db://assets sources are supported: ' + url);
        assertNotStructuredAssetPath(args.destPath, 'manage_asset(action:"copy")');
        assertNotStructuredAssetPath(url, 'manage_asset(action:"copy")');
        return await withOperationEvidence(evidenceStartedAt, async function () {
          var srcPath = editorHelpers.urlToFspath(url);
          if (!srcPath || !fs.existsSync(srcPath)) throw new Error('Source not found: ' + url);
          var dstPath = editorHelpers.urlToFspath(args.destPath);
          if (!dstPath) throw new Error('Only db://assets destinations are supported: ' + args.destPath);
          dstPath = assertInsideProject(dstPath, 'manage_asset(action:"copy")');
          if (fs.existsSync(dstPath)) throw new Error('Destination already exists: ' + args.destPath);
          fs.mkdirSync(path.dirname(dstPath), { recursive: true });
          fs.copyFileSync(srcPath, dstPath);
          await editorHelpers.refreshAssetDb(args.destPath);
          return { ok: true, path: url, destPath: args.destPath, message: 'Asset copied: ' + url + ' -> ' + args.destPath };
        }, { readConsole: args.readConsole });

      case 'get_info': {
        if (!url) throw new Error('path is required');
        var uuid = await editorHelpers.urlToUuid(url);
        if (!uuid) return { exists: false, path: url };
        var fsp = editorHelpers.urlToFspath(url);
        var info = { exists: true, path: url, uuid: uuid, fspath: fsp };
        try {
          var assetInfo = await Editor.Message.request('asset-db', 'query-asset-info', url);
          if (assetInfo) {
            info.name = assetInfo.name || info.name;
            info.type = assetInfo.type || info.type;
            info.isSubAsset = !!assetInfo.isSubAsset;
          }
        } catch (e) {}
        try {
          var metaPath = fsp + '.meta';
          if (fsp && fs.existsSync(metaPath)) {
            var metaContent = JSON.parse(fs.readFileSync(metaPath, 'utf8'));
            var subMetas = metaContent.subMetas || {};
            var subKeys = Object.keys(subMetas);
            if (subKeys.length > 0) {
              info.containsSubAssets = true;
              info.subAssets = subKeys.map(function (key) {
                var sm = subMetas[key];
                return { uuid: sm.uuid, name: sm.name || sm.displayName || key, type: sm.importer, id: key };
              });
            } else {
              info.containsSubAssets = false;
              info.subAssets = [];
            }
          } else {
            info.containsSubAssets = false;
            info.subAssets = [];
          }
        } catch (e) {
          info.containsSubAssets = false;
          info.subAssets = [];
        }
        try { var stat = fs.statSync(fsp); info.size = stat.size; info.mtime = stat.mtime; } catch (e) {}
        return info;
      }

      case 'refresh':
        if (url && String(url).indexOf('db://assets') !== 0) throw new Error('Only db://assets paths can be refreshed: ' + url);
        return await withOperationEvidence(evidenceStartedAt, async function () {
          return await editorHelpers.refreshAssetDb(url || 'db://assets/');
        }, { readConsole: args.readConsole });

      default:
        throw new Error('Unknown action: ' + args.action);
    }
  },
});

