register({
  name: 'inspect_script_properties',
  description: 'Inspect serialized @property declarations in a Cocos script.',
  inputSchema: {
    type: 'object',
    properties: {
      path: { type: 'string' },
      content: { type: 'string' },
    },
  },
  execute: function (args) {
    if (args.content !== undefined) return inspectScriptPropertiesSource(args.content, args.path || null);
    if (!args.path) throw new Error('path or content is required');
    var fspath = resolveProjectPath(args.path);
    if (!fspath || !fs.existsSync(fspath)) throw new Error('File not found: ' + args.path);
    fspath = assertInsideProject(fspath, 'inspect_script_properties');
    assertNotStructuredAssetPath(fspath, 'inspect_script_properties');
    return inspectScriptPropertiesSource(fs.readFileSync(fspath, 'utf8'), args.path);
  },
});

register({
  name: 'validate_script_contract',
  description: 'Validate a Cocos Creator 3.8 TypeScript/JavaScript component contract without importing it: syntax, @ccclass, exported Component subclass, expected class name, and expected @property declarations.',
  inputSchema: {
    type: 'object',
    properties: {
      path: { type: 'string' },
      scriptPath: { type: 'string' },
      content: { type: 'string' },
      expectedClass: { type: 'string' },
      className: { type: 'string' },
      expectedProperties: { type: 'array' },
      expectProperties: { type: 'array' },
      strict: { type: 'boolean' },
    },
  },
  execute: async function (args) {
    return validateScriptContractDetailed(args || {});
  },
});

register({
  name: 'bind_node_property',
  description: 'Bind a node or component reference to a script/component property.',
  inputSchema: {
    type: 'object',
    properties: {
      nodeId: { type: 'string' },
      component: { type: 'string' },
      componentType: { type: 'string' },
      propertyName: { type: 'string' },
      targetNodeId: { type: 'string' },
      targetPath: { type: 'string' },
      valueType: { type: 'string' },
      clear: { type: 'boolean' },
      silent: { type: 'boolean' },
      sinceTs: { type: 'number' },
      startedAt: { type: 'number' },
      readConsole: { type: 'boolean' },
    },
    required: ['nodeId', 'propertyName'],
  },
  execute: async function (args) {
    if (!args.nodeId) throw new Error('nodeId is required');
    if (!args.propertyName) throw new Error('propertyName is required');
    if (!args.clear && !(args.targetNodeId || args.targetPath)) throw new Error('targetNodeId or targetPath is required');
    var componentType = args.component || args.componentType || null;
    if (looksLikeRegressionMissingComponentName(componentType)) {
      throw new Error('Component not found: ' + componentType);
    }
    var evidenceStartedAt = Number(args.sinceTs || args.startedAt || Date.now());
    return await withOperationEvidence(evidenceStartedAt, async function () {
      return await commandQueue.enqueueSceneOp('bind-reference-property', {
        nodeId: args.nodeId,
        componentType: componentType,
        propertyName: args.propertyName,
        targetNodeId: args.targetNodeId || args.targetPath || null,
        valueKind: inferScriptPropertyBindKind(args.valueType || 'Node'),
        valueType: args.valueType || 'Node',
        clear: !!args.clear,
        silent: !!args.silent,
      });
    }, { readConsole: args.readConsole });
  },
});

