register({
  name: 'inspect_bound_property',
  description: 'Inspect the current value of one script/component property on a node.',
  inputSchema: {
    type: 'object',
    properties: {
      nodeId: { type: 'string' },
      component: { type: 'string' },
      componentType: { type: 'string' },
      propertyName: { type: 'string' },
    },
    required: ['nodeId', 'propertyName'],
  },
  execute: async function (args) {
    if (!args.nodeId) throw new Error('nodeId is required');
    if (!args.propertyName) throw new Error('propertyName is required');
    if (args.component || args.componentType) {
      await preflightNodeHasComponent(args.nodeId, args.component || args.componentType, 'Component not found');
    } else {
      await preflightSceneNodeDetail(args.nodeId, {});
    }
    return await commandQueue.enqueueSceneOp('inspect-bound-property', {
      nodeId: args.nodeId,
      componentType: args.component || args.componentType || null,
      propertyName: args.propertyName,
    });
  },
});

register({
  name: 'bind_button_click',
  description: 'Bind, replace, append, or clear a cc.Button click event handler through the editor scene context.',
  inputSchema: {
    type: 'object',
    properties: {
      nodeId: { type: 'string' },
      buttonNodeId: { type: 'string' },
      targetNodeId: { type: 'string' },
      targetPath: { type: 'string' },
      component: { type: 'string' },
      componentType: { type: 'string' },
      handler: { type: 'string' },
      method: { type: 'string' },
      customEventData: { type: 'string' },
      append: { type: 'boolean' },
      clear: { type: 'boolean' },
      silent: { type: 'boolean' },
      sinceTs: { type: 'number' },
      startedAt: { type: 'number' },
      readConsole: { type: 'boolean' },
    },
    required: ['nodeId'],
  },
  execute: async function (args) {
    var buttonNodeId = args.nodeId || args.buttonNodeId;
    if (!buttonNodeId) throw new Error('nodeId is required');
    var componentName = args.component || args.componentType || null;
    var handlerName = args.handler || args.method || null;
    if (!args.clear) {
      if (!(args.targetNodeId || args.targetPath)) throw new Error('targetNodeId or targetPath is required');
      if (!componentName) throw new Error('component is required');
      if (!handlerName) throw new Error('handler is required');
    }
    var evidenceStartedAt = Number(args.sinceTs || args.startedAt || Date.now());
    if (!args.append) {
      return await withOperationEvidence(evidenceStartedAt, async function () {
        return await commandQueue.enqueueSceneOp('manage-components', {
          nodeId: buttonNodeId,
          action: 'update',
          componentType: 'cc.Button',
          properties: {
            clickEvents: args.clear ? [] : [{
              target: args.targetNodeId || args.targetPath,
              component: componentName,
              handler: handlerName,
              customEventData: args.customEventData,
            }],
          },
          silent: !!args.silent,
        });
      }, { readConsole: args.readConsole });
    }
    return await withOperationEvidence(evidenceStartedAt, async function () {
      return await commandQueue.enqueueSceneOp('bind-button-click', {
        nodeId: buttonNodeId,
        targetNodeId: args.targetNodeId || args.targetPath || null,
        componentType: componentName,
        handler: handlerName,
        customEventData: args.customEventData,
        append: !!args.append,
        clear: !!args.clear,
        silent: !!args.silent,
      });
    }, { readConsole: args.readConsole });
  },
});

