register({
  name: 'list_assets',
  description: 'List and search project assets by type, path, or name pattern.',
  inputSchema: {
    type: 'object',
    properties: {
      type: { type: 'string' },
      path: { type: 'string' },
      pattern: { type: 'string' },
      maxResults: { type: 'number' },
    },
  },
  execute: async function (args) {
    var searchPath = args.path || 'db://assets';
    var rootPath = editorHelpers.urlToFspath(searchPath);
    if (!rootPath || !fs.existsSync(rootPath)) throw new Error('Path not found: ' + searchPath);

    var extMap = {
      'script': ['.js', '.ts'],
      'texture': ['.png', '.jpg', '.jpeg', '.bmp', '.webp'],
      'sprite-frame': ['.png', '.jpg', '.jpeg'],
      'prefab': ['.prefab'],
      'scene': ['.scene'],
      'animation-clip': ['.anim'],
      'audio-clip': ['.mp3', '.ogg', '.wav'],
      'font': ['.ttf', '.fnt'],
      'material': ['.mtl'],
    };
    var filterExts = args.type && args.type !== 'all' ? extMap[args.type] || null : null;
    var pattern = (args.pattern || '').toLowerCase();
    var results = [];
    var MAX = Math.max(1, Math.min(Number(args.maxResults) || 200, 500));

    try {
      var assetDbResults = await listAssetsFromAssetDb(searchPath, args.type || 'all', pattern, MAX);
      if (assetDbResults.length > 0) {
        return { assets: assetDbResults, count: assetDbResults.length, source: 'assetdb' };
      }
    } catch (e) {}

    (function walk(dir) {
      if (results.length >= MAX) return;
      var entries;
      try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch (e) { return; }
      for (var i = 0; i < entries.length && results.length < MAX; i++) {
        var ent = entries[i];
        if (ent.name.startsWith('.') || ent.name === 'node_modules' || ent.name === 'library' || ent.name === 'temp') continue;
        var full = path.join(dir, ent.name);
        if (ent.isDirectory()) { walk(full); continue; }
        if (!ent.isFile()) continue;
        var ext = path.extname(ent.name).toLowerCase();
        if (ext === '.meta') continue;
        if (filterExts && filterExts.indexOf(ext) === -1) continue;
        if (pattern && ent.name.toLowerCase().indexOf(pattern) === -1) continue;
        var rel = path.relative(rootPath, full).replace(/\\/g, '/');
        var dbPath = searchPath + '/' + rel;
        results.push({ name: ent.name, path: dbPath, uuid: null });
      }
    })(rootPath);

    for (var ri = 0; ri < results.length; ri++) {
      try { results[ri].uuid = await editorHelpers.urlToUuid(results[ri].path); } catch (e) {}
    }

    return { assets: results, count: results.length };
  },
});

