    finishColorBlue: num('finishColorBlue', 0.62),
    finishColorGreen: num('finishColorGreen', 0.58),
    finishColorRed: num('finishColorRed', 0.52),
    finishColorVarianceAlpha: num('finishColorVarianceAlpha', 0),
