    finishParticleSize: num('endSize', num('finishParticleSize', 4)),
    finishParticleSizeVariance: num('endSizeVar', num('finishParticleSizeVariance', 3)),
    gravityx: nestedNum('gravity', 'x', num('gravityx', -25)),
    gravityy: nestedNum('gravity', 'y', num('gravityy', 30)),
    maxParticles: num('totalParticles', num('maxParticles', 80)),
    maxRadius: num('maxRadius', 0),
    maxRadiusVariance: num('maxRadiusVariance', 0),
    minRadius: num('minRadius', 0),
    particleLifespan: num('life', num('particleLifespan', 0.45)),
    particleLifespanVariance: num('lifeVar', num('particleLifespanVariance', 0.18)),
    radialAccelVariance: num('radialAccelVariance', 0),
    radialAcceleration: num('radialAcceleration', 0),
    rotatePerSecond: num('rotatePerSecond', 0),
    rotatePerSecondVariance: num('rotatePerSecondVariance', 0),
    rotationEnd: num('rotationEnd', 0),
    rotationEndVariance: num('rotationEndVariance', 0),
    rotationStart: num('rotationStart', 0),
    rotationStartVariance: num('rotationStartVariance', 0),
    sourcePositionVariancex: nestedNum('posVar', 'x', num('sourcePositionVariancex', 30)),
    sourcePositionVariancey: nestedNum('posVar', 'y', num('sourcePositionVariancey', 8)),
    sourcePositionx: num('sourcePositionx', 0),
    sourcePositiony: num('sourcePositiony', 0),
    speed: num('speed', 70),
    speedVariance: num('speedVar', num('speedVariance', 30)),
    startColorAlpha: num('startColorAlpha', 0.75),
    startColorBlue: num('startColorBlue', 0.64),
    startColorGreen: num('startColorGreen', 0.78),
    startColorRed: num('startColorRed', 0.92),
    startColorVarianceAlpha: num('startColorVarianceAlpha', 0.2),
    startColorVarianceBlue: num('startColorVarianceBlue', 0.08),
    startColorVarianceGreen: num('startColorVarianceGreen', 0.08),
    startColorVarianceRed: num('startColorVarianceRed', 0.08),
    startParticleSize: num('startSize', num('startParticleSize', 24)),
    startParticleSizeVariance: num('startSizeVar', num('startParticleSizeVariance', 10)),
    tangentialAccelVariance: num('tangentialAccelVariance', 0),
    tangentialAcceleration: num('tangentialAcceleration', 0),
