register({
  name: 'runtime_physics_contact',
  description: 'Runtime physics contact probe boundary. Preflights physics bodies/colliders, schemas, runtime probe, and console evidence; blocks simulation/contact claims until dialog-free runtime stepping/readback exists.',
  inputSchema: {
    type: 'object',
    properties: {
      action: { type: 'string', enum: ['capabilities', 'status', 'preflight', 'probe', 'simulate', 'contact', 'wait', 'wait-for-contact'] },
      actorNodeId: { type: 'string' },
      targetNodeId: { type: 'string' },
      bodyA: { type: 'string' },
      bodyB: { type: 'string' },
      nodeA: { type: 'string' },
      nodeB: { type: 'string' },
      nodeId: { type: 'string' },
      otherNodeId: { type: 'string' },
      sinceTs: { type: 'number' },
      startedAt: { type: 'number' },
      waitMs: { type: 'number' },
      timeoutMs: { type: 'number' },
      view: { type: 'string', enum: ['scene', 'game'] },
      inspectScreenshotTargets: { type: 'boolean' },
      consoleCount: { type: 'number' },
      count: { type: 'number' },
      readWarnings: { type: 'boolean' },
      failOnWarnings: { type: 'boolean' },
      strict: { type: 'boolean' },
      hints: { type: 'array', items: { type: 'string' } },
      warningHints: { type: 'array', items: { type: 'string' } },
    },
  },
  execute: async function (args) {
    return await runRuntimePhysicsContact(args || {});
  },
});

register({
  name: 'runtime_input',
  description: 'Runtime input simulation boundary and preflight. Validates target/coordinates/handler/readback evidence and blocks unsafe runtime event injection until preview control is proven.',
  inputSchema: {
    type: 'object',
    properties: {
      action: { type: 'string', enum: ['capabilities', 'status', 'preflight', 'simulate', 'click', 'touch', 'keyboard', 'key-down', 'key-up', 'directional'] },
      event: { type: 'string', enum: ['click', 'touch-start', 'touch-end', 'touch-move', 'key-down', 'key-up', 'keyboard', 'directional'] },
      eventType: { type: 'string' },
      kind: { type: 'string' },
      type: { type: 'string' },
      nodeId: { type: 'string' },
      targetNodeId: { type: 'string' },
      nodePath: { type: 'string' },
      targetPath: { type: 'string' },
      position: { type: 'array', items: { type: 'number' } },
      coordinates: { type: 'array', items: { type: 'number' } },
      point: { type: 'object' },
      x: { type: 'number' },
      y: { type: 'number' },
      key: { type: 'string' },
      direction: { type: 'string' },
      sinceTs: { type: 'number' },
      startedAt: { type: 'number' },
      waitMs: { type: 'number' },
      view: { type: 'string', enum: ['scene', 'game'] },
      inspectScreenshotTargets: { type: 'boolean' },
      consoleCount: { type: 'number' },
      count: { type: 'number' },
      readWarnings: { type: 'boolean' },
      failOnWarnings: { type: 'boolean' },
      strict: { type: 'boolean' },
      hints: { type: 'array', items: { type: 'string' } },
      warningHints: { type: 'array', items: { type: 'string' } },
    },
  },
  execute: async function (args) {
    return await runRuntimeInput(args || {});
  },
});

