    for (var i = 0; i < resolvedKeyNodes.length; i++) {
      var keyNode = resolvedKeyNodes[i];
      try {
        var detail = keyNode.detail || await call('get_node_detail', { id: keyNode.id, includeComponents: true, includeChildren: false, silent: true, missingOk: true });
        addCheck('key_node:' + keyNode.requested, !!(detail && (detail.exists !== false) && detail.active !== false), {
          requested: keyNode.requested,
          resolvedId: keyNode.id,
          exists: !!(detail && detail.exists),
          active: !!(detail && detail.active),
          name: detail && detail.name ? detail.name : null,
          size: detail && detail.size ? detail.size : null,
        });
      } catch (e) {
        addCheck('key_node:' + keyNode.requested, false, { requested: keyNode.requested, resolvedId: keyNode.id, error: e.message });
      }
    }

