            var nx = vecX(node.position);
            var ny = vecY(node.position);
            var nax = Number(node.anchor && node.anchor[0] != null ? node.anchor[0] : node.anchor && node.anchor.x != null ? node.anchor.x : 0.5);
            var nay = Number(node.anchor && node.anchor[1] != null ? node.anchor[1] : node.anchor && node.anchor.y != null ? node.anchor.y : 0.5);
            var left = nx - nw * nax;
