      var createResult = await call('manage_prefab', { action: 'create', nodeId: sourceNodeId, path: targetPrefab.path, sinceTs: startedAt, readConsole: false });
      var saveResult = await call('manage_prefab', { action: 'save_silent', path: targetPrefab.path, sinceTs: startedAt, readConsole: false });
      var prefabValidation = await call('prefab_validate', { path: targetPrefab.path, readConsole: false, sinceTs: startedAt });
