      staticValidation: liveProofResult ? { success: liveProofResult.success === true, status: liveProofResult.status, summary: { targetPrefab: targetPrefab.path, readbackEvidenceCount: (liveProofResult.readbackEvidence || []).length } } : { success: true, status: 'blocked', summary: { prefabStateCount: prefabStates.length, mutationSuppressed: true } },
      referenceGraph: { success: false, status: liveProofResult && liveProofResult.success === true ? 'partial' : 'blocked', summary: { reason: liveProofResult && liveProofResult.success === true ? 'Reference graph proof remains a downstream retained-authoring step.' : 'Reference graph proof requires live retained prefab creation.' } },
      runtimeValidation: liveProofResult ? { success: false, status: 'blocked', blocked: true, missingCapability: 'dialog_free_runtime_visual_input_physics_proof', reason: 'Runtime proof is outside retained prefab creation proof scope.' } : { success: false, status: 'blocked', blocked: true, missingCapability: 'explicit_live_proof_authorization', reason: 'Live proof not requested or not authorized.' },
      cleanup: { included: true, success: true, retained: root, retention: 'intentional-retain-only', note: liveProofResult ? 'Created retained prefab is intentionally retained for subsequent authoring.' : 'No retained prefab was created by blocked preflight/report/status.' },
      partial: liveProofResult && liveProofResult.success === true ? [] : [{ label: 'retained_prefab_live_proof', status: 'blocked', missingCapability: 'explicit_live_proof_authorization' }],
      blocked: liveProofResult && liveProofResult.success === true ? [] : [{ label: 'retained_prefab_live_proof', status: 'blocked', interactivePromptSuppressed: true, missingCapability: 'explicit_live_proof_authorization', nextSuggestedFix: 'Run action:"prove" with explicit safety flags inside a supported live Cocos Editor context.' }],
      failures: liveProofResult && liveProofResult.status === 'failed' ? [{ label: 'retained_prefab_live_proof', status: 'failed', nextSuggestedFix: liveProofResult.nextSuggestedFix }] : [],
      consoleEvidence: liveProofResult ? liveProofResult.consoleEvidence : consoleEvidence,
      reportPath: args.reportPath || 'temp/cocos-creator-38-mcp/reports/generic-2d-showcase-prefab-live-authoring-proof.json',
      latestPath: args.latestPath || 'temp/cocos-creator-38-mcp/reports/generic-2d-showcase-prefab-live-authoring-proof-latest.json',
