          if (!fontProp || fontProp.bindKind !== 'asset' || fontProp.type !== 'Font') throw new Error('Font script property not recognized as asset binding: ' + JSON.stringify(scriptProps));
          if (!audioProp || audioProp.bindKind !== 'asset' || audioProp.type !== 'AudioClip') throw new Error('AudioClip script property not recognized as asset binding: ' + JSON.stringify(scriptProps));

