            var offlineAtlasSnapshot = offlineAtlasExport && offlineAtlasExport.rawObjects || [];
            var offlineAtlasSprite = offlineAtlasSnapshot.filter(function (entry) { return entry && entry.__type__ === 'cc.Sprite'; })[0] || null;
            var writtenAtlasUuid = offlineAtlasSprite && offlineAtlasSprite._atlas && offlineAtlasSprite._atlas.__uuid__ || null;
            if (String(writtenAtlasUuid || '') !== String(atlasAssetInfo.uuid)) {
              throw new Error('offline atlas normalization wrote wrong _atlas uuid: ' + JSON.stringify({ expectedAtlasUuid: atlasAssetInfo.uuid, writtenAtlasUuid: writtenAtlasUuid, sprite: offlineAtlasSprite, diagnostics: offlineAtlasCreated.resourceDiagnostics }));
            }
