          var staticValidation = await call('manage_scene', { action: 'validate_static', path: sourceScene });
          if (!staticValidation || !staticValidation.ok || staticValidation.objectCount < 8) throw new Error('validate_static failed: ' + JSON.stringify(staticValidation));
