          negative.push(await expectToolFailure(
            'manage_scene duplicate requires destPath',
            'manage_scene',
            { action: 'duplicate', path: sourceScene },
            /destPath is required/i
          ));

          var listed = await call('manage_scene', { action: 'list' });
          var listHit = listed && Array.isArray(listed.scenes) && listed.scenes.some(function (scene) { return scene.path === sourceScene; });
