          readbacks.push({ step: 'list_includes_scene', count: listed.count });

          var safeOpen = await call('manage_scene', { action: 'open', path: sourceScene });
          if (!safeOpen || !(safeOpen.ok === true || safeOpen.interactivePromptSuppressed === true)) {
            throw new Error('manage_scene(open) must either open safely or return a blocked safe boundary: ' + JSON.stringify(safeOpen));
          }
          readbacks.push({ step: safeOpen.ok === true ? 'open_safe' : 'open_blocked_boundary', result: safeOpen });

          var duplicated = await call('manage_scene', { action: 'duplicate', path: sourceScene, destPath: duplicatedScene, silent: true, sinceTs: Date.now(), readConsole: true });
