          var dupValidation = await call('manage_scene', { action: 'validate_static', path: duplicatedScene });
          if (!dupValidation || !dupValidation.ok) throw new Error('duplicated scene static validation failed: ' + JSON.stringify(dupValidation));
          readbacks.push({ step: 'duplicate_validate_static', validation: dupValidation });

          var renamed = await call('manage_scene', { action: 'rename', path: duplicatedScene, name: 'GeneratedSceneRenamed', silent: true, sinceTs: Date.now(), readConsole: true });
          evidence.push(assertOperationEvidence('manage_scene', 'rename', renamed));
