register({
  name: 'get_mcp_capabilities',
  description: 'Return the Cocos MCP capability matrix so callers can distinguish supported, partial, and unsupported work before editing Cocos assets.',
  inputSchema: {
    type: 'object',
    properties: {
      domain: { type: 'string' },
    },
  },
  execute: async function (args) {
    var domain = args && args.domain ? String(args.domain).toLowerCase() : null;
    var matrix = JSON.parse(JSON.stringify(MCP_CAPABILITY_MATRIX));
    var notes = {
      rule: 'Supported work must be verified through MCP/editor-visible checks. Unsupported work must be reported instead of guessed or manually serialized.',
      unsupportedResultShape: {
        ok: false,
        success: false,
        unsupported: true,
        status: 'unsupported',
        missingCapability: 'capability_key',
        supportedAlternatives: [],
        suggestedTooling: 'next MCP tool improvement',
        nextSuggestedFix: 'next MCP tool improvement',
        message: 'clear user-facing reason',
      },
      partialResultShape: {
        ok: false,
        success: false,
        partial: true,
        status: 'partial',
        reason: 'verified boundary or missing readback',
        nextSuggestedFix: 'positive readback plus negative/cleanup/console evidence',
      },
      blockedResultShape: {
        ok: false,
        success: false,
        blocked: true,
        status: 'blocked',
        interactivePromptSuppressed: true,
        nextSuggestedFix: 'use static/in-place validation until a dialog-free editor workflow exists',
      },
      failedResultShape: {
        ok: false,
        success: false,
        status: 'failed',
        error: 'clear failure reason',
      },
    };
    if (!domain) return { matrix: matrix, notes: notes };
    function filter(list) {
      return list.filter(function (item) { return item.indexOf(domain) >= 0; });
    }
    return {
      domain: domain,
      supported: filter(matrix.supported),
      partial: filter(matrix.partial),
      unsupported: filter(matrix.unsupported),
      notes: notes,
    };
  },
});

register({
  name: 'get_reserved_fixture_policy',
  description: 'Return the centralized reserved MCP fixture roots, scene-node name patterns, and retention/cleanup policy.',
  inputSchema: {
    type: 'object',
    properties: {
      cleanupPaths: { type: 'array', items: { type: 'string' } },
    },
  },
  execute: async function (args) {
    return { ok: true, success: true, status: 'passed', policy: getReservedFixturePolicy(args || {}) };
  },
});

register({
  name: 'inspect_reserved_fixtures',
  description: 'Read-only inventory of reserved MCP fixture assets and scene nodes; detects stale __mcp_* and Generic2DShowcase artifacts without cleanup mutation.',
  inputSchema: {
    type: 'object',
    properties: {
      cleanupPaths: { type: 'array', items: { type: 'string' } },
      includeSceneNodes: { type: 'boolean' },
      depth: { type: 'number' },
      maxChildren: { type: 'number' },
    },
  },
  execute: async function (args) {
    var inventory = await inventoryReservedFixtures(args || {});
    var ok = inventory.staleAssetCount === 0 && inventory.staleNodeCount === 0 && !inventory.hierarchyError;
    return Object.assign({
      ok: ok,
      success: ok,
      status: ok ? 'passed' : 'failed',
      nextSuggestedFix: ok ? null : cleanupFailureSuggestedFix(),
    }, inventory);
  },
});

register({
  name: 'unsupported_capability_matrix',
  description: 'Read-only standard unsupported/partial boundary matrix for Timeline/Cutscene, gameplay controllers, unsupported animation/material curves, Spine/IK, complex particles, protected asset edits, process lifecycle, and unsafe context switching.',
  inputSchema: {
    type: 'object',
    properties: {
      capability: { type: 'string' },
      key: { type: 'string' },
      domain: { type: 'string' },
      category: { type: 'string' },
    },
  },
  execute: async function (args) {
    return buildUnsupportedCapabilityMatrix(args || {});
  },
});

register({
  name: 'report_unsupported',
  description: 'Return a standardized unsupported MCP capability response without editing project assets.',
  inputSchema: {
    type: 'object',
    properties: {
      missingCapability: { type: 'string' },
      capability: { type: 'string' },
      requestedWork: { type: 'string' },
      request: { type: 'string' },
      supportedAlternatives: { type: 'array' },
      alternatives: { type: 'array' },
      suggestedTooling: { type: 'string' },
      nextToolTask: { type: 'string' },
      message: { type: 'string' },
    },
  },
  execute: async function (args) {
    return createUnsupportedResult(args || {});
  },
});

register({
  name: 'get_workflow_templates',
  description: 'List available workflow templates with their descriptions and required variables.',
  inputSchema: { type: 'object', properties: {} },
  execute: async function () {
    return loadWorkflows().listTemplates();
  },
});

register({
  name: 'run_workflow',
  description: 'Execute a workflow blueprint or custom workflow steps through the same HTTP tool registry.',
  inputSchema: {
    type: 'object',
    properties: {
      template: { type: 'string' },
      steps: {
        type: 'array',
        items: {
          type: 'object',
          properties: {
            tool: { type: 'string' },
            args: { type: 'object' },
            output_var: { type: 'string' },
          },
          required: ['tool'],
        },
      },
      variables: { type: 'object' },
    },
  },
  execute: async function (args) {
    var localBridge = {
      forward: async function (toolName, toolArgs) {
        if (toolName === 'run_workflow') throw new Error('Nested run_workflow is not supported');
        return await call(toolName, toolArgs || {});
      },
    };
    return await loadWorkflows().execute(localBridge, args || {});
  },
});

register({
  name: 'apply_text_edits',
  description: 'Apply find-and-replace text edits to a file.',
  inputSchema: {
    type: 'object',
    properties: {
      path: { type: 'string' },
      edits: {
        type: 'array',
        items: {
          type: 'object',
          properties: {
            find: { type: 'string' },
            replace: { type: 'string' },
            insertAfter: { type: 'string' },
            insertBefore: { type: 'string' },
            delete: { type: 'string' },
            all: { type: 'boolean' },
          },
        },
      },
    },
    required: ['path', 'edits'],
  },
  execute: async function (args) {
    var url = args.path;
    var fspath = resolveWritableProjectPath(url, 'apply_text_edits');
    if (!fs.existsSync(fspath)) throw new Error('File not found: ' + url);

    var content = fs.readFileSync(fspath, 'utf8');
    var edits = args.edits || [];
    var applied = 0;

    for (var i = 0; i < edits.length; i++) {
      var edit = edits[i];
      var replacement = edit.replace || '';
      if (edit.delete) {
        var beforeDelete = content;
        content = edit.all ? content.split(edit.delete).join('') : content.replace(edit.delete, '');
        if (content !== beforeDelete) applied++;
        continue;
      }
      if (edit.insertAfter) {
        var afterIdx = content.indexOf(edit.insertAfter);
        if (afterIdx !== -1) {
          var afterPos = afterIdx + edit.insertAfter.length;
          content = content.substring(0, afterPos) + replacement + content.substring(afterPos);
          applied++;
        }
        continue;
      }
      if (edit.insertBefore) {
        var beforeIdx = content.indexOf(edit.insertBefore);
        if (beforeIdx !== -1) {
          content = content.substring(0, beforeIdx) + replacement + content.substring(beforeIdx);
          applied++;
        }
        continue;
      }
      if (!edit.find) continue;
      if (edit.all) {
        var before = content;
        content = content.split(edit.find).join(replacement);
        if (content !== before) applied++;
      } else {
        var idx = content.indexOf(edit.find);
        if (idx !== -1) {
          content = content.substring(0, idx) + replacement + content.substring(idx + edit.find.length);
          applied++;
        }
      }
    }

    if (String(url).indexOf('db://') === 0) {
      return new Promise(function (resolve, reject) {
        assetPatcher.safeSaveExistingAsset(url, content, function (err) {
          if (err) reject(new Error(String(err)));
          else resolve('Applied ' + applied + ' edits to ' + url);
        });
      });
    }
    fs.writeFileSync(fspath, content, 'utf8');
    return 'Applied ' + applied + ' edits to ' + fspath;
  },
});

